inputs = ['ajigxy', 'cbuuju', 'ycbhdh', 'ey', 'ew']
outputs = ['ajiviczy', 'cxacuuju', 'ycxachdh', 'ey', 'ew']

# Let's examine each pair to see what changes
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Pair {i}: '{inp}' -> '{outp}'")

    # Find differences
    if len(inp) != len(outp):
        print(f"  Length difference: {len(inp)} -> {len(outp)}")
    else:
        diff_positions = []
        for j, (c1, c2) in enumerate(zip(inp, outp)):
            if c1 != c2:
                diff_positions.append((j, c1, c2))
        if diff_positions:
            print(f"  Differences at positions: {diff_positions}")
        else:
            print("  No character differences")
    print()

